# -*- coding: utf-8 -*-
"""
Exceptions used in SC5G package
"""


class SC5GException(Exception):
    pass


class HardwareException(SC5GException):
    pass


class StatusException(SC5GException):
    pass


class MegazoneFunctionalityNotSupported(SC5GException):
    pass


class COAMFunctionalityNotSupported(SC5GException):
    pass
